function detectMarket(){
  const host=(typeof window!=="undefined"&&window.location&&window.location.hostname||"").toLowerCase();
  for(const domain in MARKET_CONFIG){
    if(host===domain||host.endsWith("."+domain)||host.includes(domain)) return MARKET_CONFIG[domain];
  }
  return MARKET_CONFIG["welvaere.nl"];
}
